import React, { useState } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { UserPlus, Users, BarChart3 } from 'lucide-react';

const AdminPage = ({ userName = 'المدير', onNavigate }) => {
  const [activePage, setActivePage] = useState('dashboard'); // 'dashboard', 'addUser', 'subscribers'

  // Example user requests data
  const [requests, setRequests] = useState([
    { id: 1, name: 'محمد علي', status: 'معلق' },
    { id: 2, name: 'سارة أحمد', status: 'مكتمل' },
    { id: 3, name: 'خالد يوسف', status: 'معلق' },
  ]);

  // Subscriber info
  const [subscribersData, setSubscribersData] = useState({
    total: 125,
    active: 100,
    inactive: 25,
    plans: {
      basic: 50,
      premium: 70,
      enterprise: 5,
    },
    recent: [
      { id: 1, name: 'محمد علي', plan: 'Premium', status: 'Active' },
      { id: 2, name: 'سارة أحمد', plan: 'Basic', status: 'Inactive' },
      { id: 3, name: 'خالد يوسف', plan: 'Premium', status: 'Active' },
    ],
  });

  const handleChangePage = (page) => setActivePage(page);

  const handleStatusChange = (id, newStatus) => {
    setRequests((prev) =>
      prev.map((r) => (r.id === id ? { ...r, status: newStatus } : r))
    );
  };

  return (
    <div className="flex flex-col min-h-screen bg-gray-50" dir="rtl">
      <Header onNavigate={onNavigate} title="لوحة الإدارة" />

      <main className="flex flex-1 p-6 gap-6">
        {/* Left section - dynamic content */}
        <section className="flex-1 bg-white rounded-xl shadow p-6 transition-all duration-300">
          {activePage === 'dashboard' && (
            <>
              <h2 className="text-3xl font-bold mb-6 text-gray-800">
                مرحباً {userName}
              </h2>
              <h3 className="text-xl font-semibold mb-4 text-gray-700">
                طلبات المستخدمين
              </h3>

              <div className="overflow-x-auto">
                <table className="w-full border-collapse text-right">
                  <thead>
                    <tr className="bg-gray-200">
                      <th className="border p-2 text-left">الاسم</th>
                      <th className="border p-2 text-left">الحالة</th>
                    </tr>
                  </thead>
                  <tbody>
                    {requests.map((req) => (
                      <tr key={req.id} className="hover:bg-gray-100 transition-colors">
                        <td className="border p-2">{req.name}</td>
                        <td className="border p-2">
                          <select
                            value={req.status}
                            onChange={(e) => handleStatusChange(req.id, e.target.value)}
                            className={`p-2 rounded border focus:outline-none ${
                              req.status === 'معلق' ? 'bg-yellow-100' : 'bg-green-100'
                            }`}
                          >
                            <option value="معلق">معلق</option>
                            <option value="مكتمل">مكتمل</option>
                          </select>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </>
          )}

          {activePage === 'addUser' && (
            <div className="text-center max-w-md mx-auto">
              <h2 className="text-2xl font-bold mb-6">إضافة مستخدم جديد</h2>
              <form className="space-y-4">
                <input
                  type="text"
                  placeholder="الاسم الكامل"
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400"
                />
                <input
                  type="email"
                  placeholder="البريد الإلكتروني"
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400"
                />
                <input
                  type="password"
                  placeholder="كلمة المرور"
                  className="w-full p-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400"
                />
                <button className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold hover:bg-blue-700 transition">
                  إضافة المستخدم
                </button>
              </form>
            </div>
          )}

          {activePage === 'subscribers' && (
            <div>
              <h2 className="text-2xl font-bold mb-6">معلومات المشتركين</h2>
              <div className="grid sm:grid-cols-2 md:grid-cols-4 gap-6 mb-6">
                <div className="bg-blue-50 p-4 rounded-xl shadow text-center hover:shadow-lg transition">
                  <p className="text-gray-600 mb-1">إجمالي المشتركين</p>
                  <p className="text-3xl font-bold text-blue-600">{subscribersData.total}</p>
                </div>
                <div className="bg-green-50 p-4 rounded-xl shadow text-center hover:shadow-lg transition">
                  <p className="text-gray-600 mb-1">المشتركين النشطين</p>
                  <p className="text-3xl font-bold text-green-600">{subscribersData.active}</p>
                </div>
                <div className="bg-red-50 p-4 rounded-xl shadow text-center hover:shadow-lg transition">
                  <p className="text-gray-600 mb-1">المشتركين غير النشطين</p>
                  <p className="text-3xl font-bold text-red-600">{subscribersData.inactive}</p>
                </div>
                <div className="bg-yellow-50 p-4 rounded-xl shadow text-center hover:shadow-lg transition">
                  <p className="text-gray-600 mb-1">خطط الاشتراك</p>
                  <p className="text-lg">
                    أساسي: {subscribersData.plans.basic} <br />
                    بريميوم: {subscribersData.plans.premium} <br />
                    مؤسسي: {subscribersData.plans.enterprise}
                  </p>
                </div>
              </div>

              <h3 className="text-xl font-semibold mb-4">أحدث المشتركين</h3>
              <div className="overflow-x-auto">
                <table className="w-full border-collapse text-right">
                  <thead>
                    <tr className="bg-gray-200">
                      <th className="border p-2">الاسم</th>
                      <th className="border p-2">الخطة</th>
                      <th className="border p-2">الحالة</th>
                    </tr>
                  </thead>
                  <tbody>
                    {subscribersData.recent.map((sub) => (
                      <tr key={sub.id} className="hover:bg-gray-100 transition-colors">
                        <td className="border p-2">{sub.name}</td>
                        <td className="border p-2">{sub.plan}</td>
                        <td className="border p-2">
                          <span
                            className={`px-2 py-1 rounded text-white ${
                              sub.status === 'Active' ? 'bg-green-500' : 'bg-red-500'
                            }`}
                          >
                            {sub.status === 'Active' ? 'نشط' : 'غير نشط'}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </section>

        {/* Right sidebar */}
        <aside className="w-64 flex-shrink-0 flex flex-col gap-4 sticky top-6">
          <button
            onClick={() => handleChangePage('dashboard')}
            className={`flex items-center gap-2 p-3 rounded font-bold transition-colors ${
              activePage === 'dashboard'
                ? 'bg-gray-800 text-white'
                : 'bg-gray-700 text-white hover:bg-gray-800'
            }`}
          >
            <BarChart3 /> لوحة القيادة
          </button>

          <button
            onClick={() => handleChangePage('addUser')}
            className={`flex items-center gap-2 p-3 rounded font-bold transition-colors ${
              activePage === 'addUser'
                ? 'bg-blue-700 text-white'
                : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            <UserPlus /> إضافة مستخدم
          </button>

          <button
            onClick={() => handleChangePage('subscribers')}
            className={`flex items-center gap-2 p-3 rounded font-bold transition-colors ${
              activePage === 'subscribers'
                ? 'bg-green-700 text-white'
                : 'bg-green-600 text-white hover:bg-green-700'
            }`}
          >
            <Users /> معلومات المشتركين
          </button>
        </aside>
      </main>

      <Footer />
    </div>
  );
};

export default AdminPage;
